const r = phi.click("29");
phi.waitForNetworkIdle({ idleMs: 500, timeoutMs: 8000 });
const o = phi.observe();
return { r, url: o.url, title: o.title, text: o.text.slice(0, 3000), nodes: o.nodes.slice(0, 60).map(n => `${n.ref} ${n.role} "${n.name}"`) };

const o = phi.observe();
const api = o.nodes.find(n => n.role === "link" && /AeroAPI/.test(n.name) && n.name.trim() === "AeroAPI");
let out = { found: api ? { ref: api.ref, name: api.name } : null };
let r = null;
if (api) { r = phi.click(api.ref); }
phi.waitForNetworkIdle({ idleMs: 500, timeoutMs: 8000 });
const o2 = phi.observe();
out.r = r;
out.url = o2.url; out.title = o2.title;
out.text = o2.text.slice(0, 2500);
out.nodes = o2.nodes.slice(0, 70).map(n => `${n.ref} ${n.role} "${n.name}"`);
return out;

const o = phi.observe({ within: "#pricing-cards, [id*=pricing]", maxElements: 60 });
let out = { url: o.url };
out.nodes = o.nodes ? o.nodes.map(n => `${n.ref} ${n.role} "${n.name}"`) : null;
// also grab structure of pricing area
const info = phi.js(() => {
  const ids = Array.from(document.querySelectorAll("[id]")).map(e => e.id).filter(id => /pric|tier|card|plan/i.test(id));
  const cls = Array.from(document.querySelectorAll("[class]")).map(e => e.className).filter(c => typeof c === "string" && /pric|tier|card/i.test(c));
  const uniq = Array.from(new Set(cls)).slice(0, 40);
  return { ids, uniq };
});
out.info = info;
out.textLen = phi.text().length;
return out;

const cards = phi.query("#pricing-cards", { limit: 5 });
const out = { cardsTotal: cards.total };
out.cardsText = cards.items.map(i => i.text);
const t = phi.js(() => {
  const el = document.querySelector('#pricing-cards');
  const t2 = document.querySelector('#pricing-table');
  const tbl = document.querySelector('#compare-tiers');
  const grab = (n) => n ? n.innerText.replace(/\n{2,}/g, '\n').slice(0, 4000) : null;
  return { cards: grab(el), table: grab(t2), compare: grab(tbl) };
});
out.js = t;
return out;

const prev = phi.recall("$step7");
const rest = prev.js.compare.slice(3800);
const rows = phi.js(() => {
  const t = document.querySelector('#compare-tiers');
  if (!t) return { err: 'no table' };
  const out = [];
  t.querySelectorAll('tr').forEach(tr => {
    const cells = Array.from(tr.children).map(td => td.innerText.replace(/\s+/g, ' ').trim());
    out.push(cells.join(' | '));
  });
  return { rowCount: out.length, rows: out };
});
phi.keep("aeroapi_compare_rows", rows);
return { tailOfCompare: rest, rows };

const o = phi.observe({ within: "#compare-tiers", maxElements: 30 });
phi.js(() => { const el = document.querySelector('#compare-tiers'); if (el) el.scrollIntoView({block:'center'}); return true; });
phi.sleep(500);
const vis = phi.observe({ viewportOnly: true, maxElements: 40 });
return { url: o.url, nodes: o.nodes.map(n => n.ref + ' ' + n.role + ' "' + n.name + '"'), visible: vis.nodes ? vis.nodes.map(n => n.role + ' "' + n.name + '"') : null, total: o.total };

const info = phi.js(() => {
  const grab = (sel) => { const el = document.querySelector(sel); return el ? el.innerText.replace(/\n{2,}/g,'\n').trim() : null; };
  const body = document.body.innerText;
  const idx = body.indexOf('Enterprise');
  const entCtx = idx >= 0 ? body.slice(Math.max(0, idx-300), idx+400) : null;
  // discounting details if in DOM
  const disc = (() => {
    const nodes = Array.from(document.querySelectorAll('div,section,table'));
    const hit = nodes.find(n => /Volume Discount/i.test(n.innerText||'') && (n.innerText||'').length < 1200 && /%/.test(n.innerText||''));
    return hit ? hit.innerText.replace(/\n{2,}/g,'\n').trim() : null;
  })();
  const freeCtx = (() => { const i = body.indexOf('$5 free'); return i>=0 ? body.slice(Math.max(0,i-300), i+300) : null; })();
  return { aeroapiIntro: grab('main') ? grab('main').slice(0,1500) : null, entCtx, disc, freeCtx, title: document.title };
});
phi.keep("aeroapi_context", info);
return info;

// Grab the three plan cards' full text including prices
const cards = phi.js(() => {
  const clean = s => (s||'').replace(/\n{2,}/g,'\n').trim();
  const body = document.body.innerText;
  // find pricing card region: search for text nodes containing tier names + $ amounts
  const out = {};
  const cands = Array.from(document.querySelectorAll('div,section,article'));
  const tierCards = cands.filter(n => {
    const t = clean(n.innerText);
    return t && t.length < 900 && /Personal/.test(t) && /Standard/.test(t) === false || (t && t.length < 900 && /(Premium|Standard)/.test(t) && /\$\d/.test(t));
  });
  out.tierCards = tierCards.slice(0, 12).map(n => ({ cls: n.className, tag: n.tagName, text: clean(n.innerText).slice(0,600) }));
  // collect all $ mentions in body with context
  const prices = [];
  const re = /\$[\d,]+(\.\d+)?[^\n]{0,60}/g;
  let m;
  while ((m = re.exec(body)) && prices.length < 40) {
    prices.push(body.slice(Math.max(0, m.index - 120), m.index + 80).replace(/\n{2,}/g,'\n').trim());
  }
  out.priceContexts = prices;
  return out;
});
return cards;

const rows = phi.recall("aeroapi_compare_rows");
const ctx = phi.recall("aeroapi_context");
// Pull the volume discount table fully, which is truncated elsewhere
const disc = phi.js(() => {
  const clean = s => (s || '').replace(/\n{2,}/g, '\n').trim();
  const secs = Array.from(document.querySelectorAll('section,div'));
  const hit = secs.filter(n => /Volume Discounting/.test(n.innerText || '') && /94%/.test(n.innerText || '')).sort((a,b)=>a.innerText.length-b.innerText.length)[0];
  const table = hit ? clean(hit.innerText).slice(0, 1200) : null;
  // tier card summaries: name + description + key numbers
  const cards = Array.from(document.querySelectorAll('div.w-full.justify-self-center'));
  const cardTexts = cards.map(c => clean(c.innerText).slice(0, 400)).filter(t => /Get started/.test(t));
  return { table, cardTexts };
});
return { rows: rows.rows, rowCount: rows.rowCount, discTable: disc.table, cards: disc.cardTexts };

const disc = phi.js(() => {
  const clean = s => (s || '').replace(/\n{2,}/g, '\n').trim();
  // find the discount comparison table rows
  const tables = Array.from(document.querySelectorAll('table'));
  const t = tables.find(tb => /94%/.test(tb.innerText || '') || /30% Discount/.test(tb.innerText || ''));
  const rows = t ? Array.from(t.querySelectorAll('tr')).map(tr => clean(tr.innerText).replace(/\n/g, ' | ')) : [];
  const sec = Array.from(document.querySelectorAll('section,div')).filter(n => /Volume Discounting/.test(n.innerText || '') && /30% Discount/.test(n.innerText || '')).sort((a,b)=>a.innerText.length-b.innerText.length)[0];
  return { rows, sectionText: sec ? clean(sec.innerText).slice(0, 1500) : null };
});
phi.keep("aeroapi_discount", disc);
return disc;

const links = phi.query("a[href*='pric'], a[href*='per-query'], a[href*='fee'], a[href*='aeroapi']", { fields: ["href"], limit: 40 });
const btns = phi.query("button, [role=button]", { fields: ["type"], limit: 60 });
return { links: links.items, linkTotal: links.total, btns: btns.items.filter(b => /fee|pric|discount/i.test(b.text || "")).slice(0,20), btnTotal: btns.total };

phi.narrate("Checking the per-query fee table, the last piece of the pricing");
const el = phi.waitForElement("#pricing-table", 5000);
const fees = phi.js(() => {
  const clean = s => (s || '').replace(/\n{2,}/g, '\n').trim();
  const t = document.querySelector('#pricing-table');
  if (!t) return { found: false };
  const tables = Array.from(t.querySelectorAll('table'));
  const rows = tables.map(tb => Array.from(tb.querySelectorAll('tr')).map(tr => clean(tr.innerText).replace(/\n/g, ' | ')));
  return { found: true, head: clean(t.innerText).slice(0, 800), tableCount: tables.length, rows: rows.slice(0, 3).map(r => r.slice(0, 60)) };
});
phi.keep("aeroapi_perquery", fees);
return fees;

const ctx = phi.recall("aeroapi_context");
const cmp = phi.recall("aeroapi_compare_rows");
const pq = phi.recall("aeroapi_perquery");
return { ctx, cmpRows: cmp.rows, pqHead: pq.head.slice(0,600) };

phi.narrate("Reading the three plan cards themselves for the headline prices");
const el = phi.waitForElement("#pricing-cards", 5000);
const cards = phi.js(() => {
  const clean = s => (s || '').replace(/[ \t]+/g, ' ').replace(/\n{2,}/g, '\n').trim();
  const wrap = document.querySelector('#pricing-cards');
  if (!wrap) return { found: false };
  const c = Array.from(wrap.querySelectorAll('h2, h3, [class*=card], [class*=tier], [class*=plan]'));
  const texts = [...new Set(c.map(e => clean(e.innerText)).filter(t => t && t.length < 900))];
  return { found: true, block: clean(wrap.innerText).slice(0, 3000), texts: texts.slice(0, 8) };
});
const disc = phi.recall("aeroapi_discount");
phi.keep("aeroapi_cards", { block: cards.block, disc });
return { block: cards.block, disc: disc.rows };

phi.narrate("One last look at the plan cards for the headline monthly prices");
const info = phi.js(() => {
  const clean = s => (s || '').replace(/[ \t]+/g, ' ').replace(/\n{2,}/g, '\n').trim();
  const out = [];
  // any element whose text looks like a price, with its ancestors context
  const all = Array.from(document.querySelectorAll('#pricing-cards *, #pricing-table *'));
  const priced = all.filter(e => e.children.length === 0 && /\$\s?\d/.test(e.textContent) && e.textContent.length < 60);
  const seen = new Set();
  for (const e of priced) {
    const t = clean(e.textContent);
    if (seen.has(t)) continue;
    seen.add(t);
    const card = e.closest('[class*=card],[class*=tier],[class*=plan],li,div');
    out.push({ price: t, ctx: clean((card && card.innerText) || '').slice(0, 160) });
  }
  return out.slice(0, 25);
});
phi.keep("aeroapi_prices", info);
return info;

const pq = phi.recall("aeroapi_perquery");
const keys = Object.keys(pq || {});
const head = (pq && pq.head) ? String(pq.head) : "";
phi.keep("aeroapi_perquery_shape", { keys, headLen: head.length, head: head.slice(0, 2500) });
return { keys, headLen: head.length, head: head.slice(0, 2200) };

const rows = phi.recall("aeroapi_compare_rows").rows;
const disc = phi.recall("aeroapi_discount").rows;
const cards = phi.recall("aeroapi_cards").block;
const pq = phi.recall("aeroapi_perquery");

// pull the headline pricing features straight out of the comparison rows for the three tiers
const pick = (label) => rows.find(r => r.startsWith(label));
const summary = {
  tiers: ["Personal", "Standard", "Premium"],
  pricing: pick("Pricing (View Per-Query Fees)"),
  monthlyMinimum: pick("Monthly minimum fee"),
  rateLimit: pick("Result set rate limit"),
  historyLimit: pick("History Results set rate limit"),
  volumeDiscount: pick("Volume Discounting"),
  uptime: pick("Up-time guarantee"),
  support: [pick("E-mail Support"), pick("Phone Support"), pick("Invoicing Available")],
  includedApis: rows.filter(r => /^(Alerts|FlightAware Foresight|Aireon|Historical Flight Data|Static maps)/.test(r)),
  rights: rows.filter(r => /^(Internal Use for Business|Commercialization for Business to Consumer|Commercialization for Business to Business|Internal Use for Personal|Academic)/.test(r)),
  discountLadder: disc.slice(1),
  freeNote: "Per-query usage fees, up to $5 free per month (or $10 free per month for ADS-B feeders)",
  cardText: cards,
  perQuerySample: (pq.head || "").slice(0, 400)
};
phi.keep("aeroapi_final", summary);
return { tiers: summary.tiers.length, rowsTotal: rows.length, min: summary.monthlyMinimum, discountSteps: summary.discountLadder.length };

const c = phi.recall("aeroapi_cards");
const f = phi.recall("aeroapi_final");
phi.narrate("Checking the plan cards for the starting price lines");
return { cards: (c.block || "").slice(0, 1800), discount: f.discountLadder, freeNote: f.freeNote };
